func crystallineToString(value js.Value) (string, error) {
	var zero string

	if value.Type() != js.TypeString {
		return zero, errors.New("expected a string")
	}

	return string(value.String()), nil
}

func crystallineToTimeDuration(value js.Value) (time.Duration, error) {
	if value.Type() != js.TypeNumber {
		return 0, errors.New("expected a number of milliseconds")
	}

	return time.Duration(value.Float() * 1e6), nil
}

func crystallineToTimeTime(value js.Value) (time.Time, error) {
	if !value.InstanceOf(js.Global().Get("Date")) {
		return time.Time{}, errors.New("expected a Date")
	}

	return time.UnixMilli(int64(value.Call("getTime").Float())).UTC(), nil
}

